def backtrack(current_state):
    if solution_found:
        save_solution()
        return

    for choice in possible_choices:
        make_choice(choice)

        if valid(choice):
            backtrack(next_state)

        undo_choice(choice)

def explore(level):
    if level == 3:
        return

    print('Level:', level)

    explore(level + 1)

explore(0)
